import * as Hammer from 'hammerjs';

export function addPinchEventBlocker(element: HTMLElement): void {
    const pinchCapture = new Hammer(element, { domEvents: true, touchAction: 'pan', recognizers: [[Hammer.Pinch, { enable: true }]] });

    pinchCapture.on('pinch pinchend pinchmove pinchin pinchout pinchstart pinchcancel doubletap', (event: HammerInput) => {
        event.preventDefault();
    });
}
